package cn.huankan.stream;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications")public class NotificationController {
 private final JdbcTemplate db;public NotificationController(JdbcTemplate db){this.db=db;}public record Review(long outboxId,String messageClass,UUID factId,String actor,String reason){}
 @PostMapping("/review")public Object review(@RequestBody Review q){if(q.outboxId()<1||q.messageClass()==null||!Set.of("SOURCE_EVENT","RESEARCH_CANDIDATE","VERIFIED_FACT","IMPORTANT_ALERT","BACKFILL","REVISION").contains(q.messageClass())||q.actor()==null||q.actor().isBlank()||q.actor().length()>200||q.reason()==null||q.reason().length()<10||q.reason().length()>4000)throw new IllegalArgumentException("消息资格审核参数不足");db.update("INSERT INTO notification_review(outbox_id,message_class,fact_id,actor,reason) VALUES(?,?,?,?,?)",q.outboxId(),q.messageClass(),q.factId(),q.actor(),q.reason());return Map.of("message","消息资格审核已保存，采集Outbox与证据保留；新增审核通知位置，重复资格不再提醒");}
 @PostMapping("/status")public Object status(){return Map.of("classes",db.queryForList("SELECT message_class,base_class,count(*) records,count(*) FILTER(WHERE official_eligible) official_eligible,count(*) FILTER(WHERE important_alert_eligible) important_eligible FROM notification_qualification GROUP BY message_class,base_class ORDER BY message_class,base_class"),"filtered_batches",db.queryForList("SELECT subscription_scope,sum(scanned) scanned,sum(sent) sent,sum(excluded) excluded FROM stream_filter_batch b JOIN stream_connection c ON c.id=b.connection_id GROUP BY subscription_scope"));}
 @ExceptionHandler({IllegalArgumentException.class,org.springframework.dao.DataAccessException.class})public org.springframework.http.ResponseEntity<?> invalid(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","资格未通过：重大提醒须有非回填的官方结构化事实与审核依据"));}
}
